import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { getGearById } from "@/services/inventoryService";
import { calculateRentalPrice, formatPrice } from "@/lib/date-utils";

// Request schema
const rentalRequestSchema = z.object({
  gearId: z.string().min(1),
  startDate: z.string().datetime(),
  endDate: z.string().datetime(),
});

// Mock rental ID generator
function generateRentalId(): string {
  const timestamp = Date.now().toString(36).toUpperCase();
  const random = Math.random().toString(36).substring(2, 6).toUpperCase();
  return `RMG-${timestamp}-${random}`;
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();

    // Validate request
    const validation = rentalRequestSchema.safeParse(body);
    if (!validation.success) {
      return NextResponse.json(
        {
          error: "Invalid request",
          details: validation.error.issues,
        },
        { status: 400 }
      );
    }

    const { gearId, startDate, endDate } = validation.data;

    // Get gear item
    const item = await getGearById(gearId);
    if (!item) {
      return NextResponse.json(
        { error: "Gear item not found" },
        { status: 404 }
      );
    }

    // Calculate pricing
    const start = new Date(startDate);
    const end = new Date(endDate);
    const pricing = calculateRentalPrice(item.dailyRate, start, end);

    // Generate confirmation
    const confirmation = {
      id: generateRentalId(),
      gearId: item.id,
      gearName: item.name,
      startDate,
      endDate,
      totalDays: pricing.days,
      dailyRate: pricing.dailyRate,
      totalPrice: pricing.total,
      formattedTotal: formatPrice(pricing.total),
      status: "confirmed" as const,
      createdAt: new Date().toISOString(),
    };

    // Log the rental (in production, save to database)
    console.log("Rental confirmed:", confirmation);

    // Simulate a small delay for realism
    await new Promise((resolve) => setTimeout(resolve, 500));

    return NextResponse.json(confirmation, { status: 201 });
  } catch (error) {
    console.error("Rental API error:", error);

    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

export async function GET() {
  return NextResponse.json(
    { message: "Use POST to create a rental" },
    { status: 405 }
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ArrowLeft, Receipt, Loader2 } from "lucide-react";
import { GearItem } from "@/lib/validation";
import {
  formatDate,
  formatPrice,
  calculateRentalPrice,
} from "@/lib/date-utils";
import type { RentalDates } from "./index";

interface PriceSummaryProps {
  item: GearItem;
  dates: RentalDates;
  onConfirm: () => Promise<void>;
  onBack: () => void;
}

export function PriceSummary({
  item,
  dates,
  onConfirm,
  onBack,
}: PriceSummaryProps) {
  const [isLoading, setIsLoading] = useState(false);

  const pricing = calculateRentalPrice(
    item.dailyRate,
    dates.startDate,
    dates.endDate
  );

  const handleConfirm = async () => {
    setIsLoading(true);
    try {
      await onConfirm();
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Card>
      <CardHeader className="pb-4">
        <div className="flex items-center gap-2">
          <Button variant="ghost" size="icon" onClick={onBack} disabled={isLoading}>
            <ArrowLeft className="w-5 h-5" />
          </Button>
          <CardTitle className="text-lg flex items-center gap-2">
            <Receipt className="w-5 h-5" />
            Resumen de Renta
          </CardTitle>
        </div>
      </CardHeader>

      <CardContent className="space-y-6">
        {/* Item details */}
        <div className="bg-muted/50 rounded-lg p-4">
          <h4 className="font-semibold mb-2">{item.name}</h4>
          <p className="text-sm text-muted-foreground">{item.description}</p>
        </div>

        {/* Dates */}
        <div className="space-y-2">
          <h4 className="font-medium text-sm text-muted-foreground uppercase tracking-wide">
            Período de Renta
          </h4>
          <div className="flex justify-between items-center py-2 border-b">
            <span className="text-muted-foreground">Fecha inicio</span>
            <span className="font-medium">{formatDate(dates.startDate)}</span>
          </div>
          <div className="flex justify-between items-center py-2 border-b">
            <span className="text-muted-foreground">Fecha fin</span>
            <span className="font-medium">{formatDate(dates.endDate)}</span>
          </div>
          <div className="flex justify-between items-center py-2">
            <span className="text-muted-foreground">Duración</span>
            <span className="font-medium">
              {pricing.days} {pricing.days === 1 ? "día" : "días"}
            </span>
          </div>
        </div>

        {/* Pricing breakdown */}
        <div className="space-y-2">
          <h4 className="font-medium text-sm text-muted-foreground uppercase tracking-wide">
            Desglose de Precio
          </h4>
          <div className="flex justify-between items-center py-2 border-b">
            <span className="text-muted-foreground">
              Tarifa diaria
            </span>
            <span className="font-medium">{formatPrice(pricing.dailyRate)}</span>
          </div>
          <div className="flex justify-between items-center py-2 border-b">
            <span className="text-muted-foreground">
              {formatPrice(pricing.dailyRate)} x {pricing.days} días
            </span>
            <span className="font-medium">{formatPrice(pricing.subtotal)}</span>
          </div>
          <div className="flex justify-between items-center py-3 bg-primary/5 rounded-lg px-3 -mx-3">
            <span className="font-semibold text-lg">Total</span>
            <span className="font-bold text-xl text-primary">
              {formatPrice(pricing.total)}
            </span>
          </div>
        </div>

        {/* Confirm button */}
        <Button
          onClick={handleConfirm}
          className="w-full h-12"
          disabled={isLoading}
        >
          {isLoading ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Procesando...
            </>
          ) : (
            "Confirmar Renta"
          )}
        </Button>

        <p className="text-xs text-center text-muted-foreground">
          Al confirmar, aceptas los términos y condiciones del servicio de renta.
        </p>
      </CardContent>
    </Card>
  );
}

