3	/**
4	 * Category IDs used in the application
5	 */
6	export const CATEGORY_IDS = [
7	  "fotografia-video",
8	  "montana-camping",
9	  "deportes-acuaticos",
10	] as const;
11	
12	export type CategoryId = (typeof CATEGORY_IDS)[number];
13	
14	/**
15	 * Category display information (Spanish UI)
16	 */
17	export const CATEGORIES: Record<CategoryId, { name: string; description: string }> = {
18	  "fotografia-video": {
19	    name: "Fotografía y Video",
20	    description: "Cámaras, lentes, iluminación y equipo audiovisual profesional",
21	  },
22	  "montana-camping": {
23	    name: "Montaña y Camping",
