25	  },
26	  "deportes-acuaticos": {
27	    name: "Deportes Acuáticos",
28	    description: "Kayaks, SUP, equipo de buceo, surf y deportes náuticos",
29	  },
30	};
31	
32	/**
33	 * Schema for gear item specifications
34	 */
35	export const gearSpecsSchema = z.record(z.string(), z.union([z.string(), z.number()]));
36	
37	/**
38	 * Schema for a gear item from inventory
39	 */
40	export const gearItemSchema = z.object({
41	  id: z.string().min(1, "ID is required"),
42	  name: z.string().min(1, "Name is required"),
43	  category: z.enum(CATEGORY_IDS),
44	  description: z.string(),
45	  specs: gearSpecsSchema,
46	  dailyRate: z.number().positive("Daily rate must be positive"),
47	  imageURL: z.string().url().nullable(),
48	});
49	
50	export type GearItem = z.infer<typeof gearItemSchema>;
51	
52	/**
53	 * Schema for rental date selection
54	 * Validates that dates are not in the past, end date is after start date,
55	 * and rental duration does not exceed 30 inclusive days.
56	 */
57	export const MAX_RENTAL_DAYS = 30;
58	
59	export const rentalDatesSchema = z
60	  .object({
61	    startDate: z.date(),
62	    endDate: z.date(),
63	  })
64	  .refine(
65	    (data) => {
66	      const today = new Date();
67	      today.setHours(0, 0, 0, 0);
68	      return data.startDate >= today;
69	    },
70	    {
71	      message: "La fecha de inicio no puede ser en el pasado",
72	      path: ["startDate"],
73	    }
74	  )
75	  .refine(
76	    (data) => {
77	      return data.endDate >= data.startDate;
78	    },
79	    {
80	      message: "La fecha de fin debe ser igual o posterior a la fecha de inicio",
81	      path: ["endDate"],
82	    }
83	  )
84	  .refine(
85	    (data) => {
86	      const msPerDay = 1000 * 60 * 60 * 24;
87	      const inclusiveDays =
88	        Math.round(Math.abs(data.endDate.getTime() - data.startDate.getTime()) / msPerDay) + 1;
89	      return inclusiveDays <= MAX_RENTAL_DAYS;
90	    },
91	    {
92	      message: `La renta no puede exceder ${MAX_RENTAL_DAYS} días`,
93	      path: ["endDate"],
94	    }
95	  );
96	
97	export type RentalDates = z.infer<typeof rentalDatesSchema>;
98	
99	/**
100	 * Schema for a complete rental request
101	 */
102	export const rentalRequestSchema = z.object({
103	  gearId: z.string().min(1, "Gear ID is required"),
104	  startDate: z.string().datetime(),
105	  endDate: z.string().datetime(),
106	  customerName: z.string().min(2, "El nombre debe tener al menos 2 caracteres"),
107	  customerEmail: z.string().email("Email inválido"),
108	});
109	
110	export type RentalRequest = z.infer<typeof rentalRequestSchema>;
111	
112	/**
113	 * Schema for rental confirmation response
114	 */
115	export const rentalConfirmationSchema = z.object({
116	  id: z.string(),
117	  gearId: z.string(),
118	  gearName: z.string(),
119	  startDate: z.string(),
120	  endDate: z.string(),
121	  totalDays: z.number(),
122	  dailyRate: z.number(),
123	  totalPrice: z.number(),
124	  status: z.enum(["confirmed", "pending", "cancelled"]),
125	  createdAt: z.string(),
126	});
127	
128	export type RentalConfirmation = z.infer<typeof rentalConfirmationSchema>;
129	
130	/**
131	 * Validate a gear item from inventory
132	 */
133	export function validateGearItem(data: unknown): GearItem {
134	  return gearItemSchema.parse(data);
135	}
136	
137	/**
138	 * Validate rental dates (returns result object instead of throwing)
139	 */
140	export function validateRentalDates(startDate: Date, endDate: Date) {
141	  return rentalDatesSchema.safeParse({ startDate, endDate });
142	}
143	
144	/**
145	 * Check if a category ID is valid
146	 */
147	export function isValidCategory(id: string): id is CategoryId {
148	  return CATEGORY_IDS.includes(id as CategoryId);
149	}
